# Para birimi sembol/sözcükleri — fiyat token'larını yemek adlarından ayırt etmek
# için soyulur. Sözcük biçimleri (tl/kr…) yalnızca TEK BAŞINA eşleşir (etrafında
# harf yokken) ki "Kraft", "Tatlı" gibi yemek adlarının içinden kesilmesin.
_CURRENCY_RE = re.compile(
    r'[₺$€£]|(?<![^\W\d_])(?:tl|try|kr|krs|kurus|kuruş)(?![^\W\d_])',
    re.IGNORECASE,
)


# Framework-state atama desenleri (INF-6). Yalnızca atamanın BAŞINI yakalar;
# JSON gövdesi regex ile DEĞİL, brace-depth ile doğrusal kesilir → geri-izleme yok.
_FW_STATE_ASSIGN_PATTERNS = [
    (re.compile(r'window\.__NEXT_DATA__\s*=\s*'), "next"),
    (re.compile(r'window\.__NUXT__\s*=\s*'), "nuxt"),
    (re.compile(r'window\.__DATA__\s*=\s*'), "data"),
    (re.compile(r'window\.__INITIAL_STATE__\s*=\s*'), "state"),
]
# Doğrusal brace taramasına üst sınır — kötü niyetli devasa girdide tek thread'i
# uzun süre meşgul etmesin (linear ama yine de sınırlı tut).
_FW_STATE_MAX_JSON = 2_000_000


def _is_price_noise(text):
    """Yemek ADI değil, yalnızca fiyat/sayı/para birimi olan satırları yakalar
    (örn. "120", "₺120", "120 TL", "85,50", "1.250,00 ₺", kategori sayacı "10").
    Bunlar menü metnine gürültü katar ve çıkarım LLM'inin token bütçesini/odağını
    boşa harcar.

    Yaklaşım: para birimi sembol/sözcüklerini ve ayraç/boşlukları (.,/space) sil;
    geriye yalnızca rakam kalıyorsa fiyat gürültüsüdür. Harf içeren her şey
    ("Acılı Burger 120₺", "7Up", "100% Juice") yemek olarak KORUNUR — böylece
    hiçbir yemek adı yanlışlıkla düşmez."""
    stripped = _CURRENCY_RE.sub("", text)
    stripped = re.sub(r"[\s.,]", "", stripped)
    return stripped.isdigit() and len(stripped) > 0


def _extract_framework_state(html_text, soup=None):
    """`soup` verilirse aynı HTML yeniden parse edilmez (çağıranın zaten
    parse ettiği ağaç kullanılır — script tag'leri decompose edilmeden
    çağrılmalı). Verilmezse eski davranış: kendi parse'ını yapar."""
    import re

    if soup is None:
        soup = bounded_soup(html_text)
    script_tag = soup.find("script", {"id": "__NEXT_DATA__"})
    if script_tag and script_tag.string:
        try:
            state = bounded_json(script_tag.string)
            return state, "next"
        except (json.JSONDecodeError, ValueError):
            pass

    # INF-6: Eskiden bu yol `({.+})...</script>` GREEDY + re.DOTALL desenini ~3 MB'a
    # varan ham HTML üzerinde çalıştırıyordu; hazırlanmış/şişkin bir sayfada çok
    # sayıda `{`/`</script>` ağır geri-izleme (backtracking) ile tek worker
    # thread'inde CPU amplifikasyonu yaratabiliyordu (INF-5 ile birleşince kötüleşir).
    # Onun yerine: atamayı SINIRLI bir desenle (yalnızca `\s*`, geri-izleme yok) bul,
    # sonra süslü-parantez derinliğini DOĞRUSAL (O(n)) yürüyerek JSON'ı kes. Aynı
    # brace-depth semantiği korunur; json.loads sonucu doğrular.
    for pattern, framework in _FW_STATE_ASSIGN_PATTERNS:
        m = pattern.search(html_text)
        if not m:
            continue
        start = m.end()
        if start >= len(html_text) or html_text[start] != '{':
            continue
        depth = 0
        end_idx = 0
        scan_limit = min(len(html_text), start + _FW_STATE_MAX_JSON)
        for i in range(start, scan_limit):
            ch = html_text[i]
            if ch == '{':
                depth += 1
            elif ch == '}':
                depth -= 1
                if depth == 0:
                    end_idx = i + 1
                    break
        if end_idx > start:
            try:
                state = bounded_json(html_text[start:end_idx])
                return state, framework
            except (json.JSONDecodeError, ValueError):
                continue
    return None, None


def _discover_menu_links(soup, base_parsed):
    from urllib.parse import urljoin, urlparse
    menu_keywords = (
        "menu", "yemek", "yiyecek", "kahvalt", "icecek", "tatl", "salata",
        "pizza", "burger", "makarna", "et", "tavuk", "balik", "corba",
        "aperatif", "ara-sicak", "meze", "soguk", "sicak", "izgara",
        "food", "dish", "breakfast", "lunch", "dinner", "drinks",
    )
    base_origin = f"{base_parsed.scheme}://{base_parsed.hostname}"
    found = set()
    for a in soup.find_all("a", href=True):
        href = a["href"].strip()
        if href.startswith("#") or href.startswith("javascript:") or href.startswith("mailto:"):
            continue
        full_url = urljoin(base_origin + base_parsed.path, href)
        link_parsed = urlparse(full_url)
        if link_parsed.hostname != base_parsed.hostname:
            continue
        path_lower = link_parsed.path.lower()
        if any(kw in path_lower for kw in menu_keywords):
            clean = f"{link_parsed.scheme}://{link_parsed.hostname}{link_parsed.path}"
            if clean not in found and clean != f"{base_parsed.scheme}://{base_parsed.hostname}{base_parsed.path}":
                found.add(clean)
    return list(found)[:10]


def _extract_page_sections(html_text, soup_clean):
    import re as _re

    sections = SectionAccumulator()

    jsonld_scripts = soup_clean.find_all("script", {"type": "application/ld+json"})
    for script in jsonld_scripts:
        if script.string:
            try:
                ld = bounded_json(script.string)
                items = ld if isinstance(ld, list) else [ld]
                for item in items:
                    # B18: JSON-LD listesi string/null da içerebilir → .get()
                    # AttributeError'ı (json.JSONDecodeError, TypeError) yakalamasını
                    # aşıp kaçardı. Dict olmayanları atla.
                    if not isinstance(item, dict):
                        continue
                    if item.get("@type") in ("Menu", "MenuSection", "Restaurant"):
                        menu_sec = item.get("hasMenuSection", [])
                        if not isinstance(menu_sec, list):
                            menu_sec = [menu_sec]
                        for sec in menu_sec:
                            if not isinstance(sec, dict):
                                continue
                            cat = sec.get("name", "Genel")
                            menu_items = sec.get("hasMenuItem", [])
                            if not isinstance(menu_items, list):
                                menu_items = [menu_items]
                            names = [mi.get("name", "") for mi in menu_items
                                     if isinstance(mi, dict) and mi.get("name")]
                            if names:
                                sections.append({"category": cat, "text": "\n".join(str(n)[:500] for n in names[:80])})
            except (ValueError, TypeError):
                pass
    if sections:
        return bound_sections(sections)

    current_heading = "Genel"
    current_items = []
    # Aynı metnin hem kapsayıcı (div) hem çocuğunda (span/p) tekrar yakalanmasını
    # önle — kart başlıkları çoğu temada iç içe sarmalanır, bu da menü metnini
    # ikiye/üçe katlayıp 18000-karakter ve LLM token bütçesini boşa harcar.
    # Tekilleştirme KATEGORİ İÇİNDE yapılır: aynı yemek farklı kategorilerde
    # (örn. "Makarna Salatası" hem Makarnalar hem Salatalar) meşru tekrarlanabilir.
    current_seen = set()

    for el in soup_clean.find_all(["h1", "h2", "h3", "h4", "h5", "p", "li", "span", "div", "td"]):
        text = bounded_text(el, 501)
        if not text or len(text) < 2:
            continue
        if el.name in ("h1", "h2", "h3", "h4", "h5"):
            if current_items:
                sections.append({"category": current_heading, "text": "\n".join(current_items)})
                current_items = []
                current_seen = set()
            current_heading = text[:256]
        else:
            if 3 < len(text) < 500 and not _is_price_noise(text):
                key = " ".join(text.casefold().split())
                if key not in current_seen:
                    current_seen.add(key)
                    current_items.append(text)

    if current_items:
        sections.append({"category": current_heading, "text": "\n".join(current_items)})

    if not sections:
        menu_containers = soup_clean.find_all(
            ["div", "section", "ul"],
            class_=_re.compile(r'menu|food|dish|product|item|category', _re.IGNORECASE)
        )
        for container in menu_containers:
            items = []
            seen = set()
            for el in container.find_all(["h4", "h3", "h2", "p", "li", "span", "div"]):
                text = bounded_text(el, 501)
                if text and 3 < len(text) < 500 and not _is_price_noise(text):
                    key = " ".join(text.casefold().split())
                    if key not in seen:
                        seen.add(key)
                        items.append(text)
            if items:
                sections.append({"category": "Genel", "text": "\n".join(items)})

    if not sections:
        container = soup_clean.find("main") or soup_clean.find("article") or soup_clean.find("body")
        if container:
            fallback_items = []
            seen = set()
            for el in container.find_all(["h4", "h3", "h2", "p", "li", "span"]):
                text = bounded_text(el, 501)
                if text and 3 < len(text) < 500 and not _is_price_noise(text):
                    key = " ".join(text.casefold().split())
                    if key not in seen:
                        seen.add(key)
                        fallback_items.append(text)
            if fallback_items:
                sections.append({"category": "Genel", "text": "\n".join(fallback_items)})

    return bound_sections(sections)


_FOOD_KEYWORDS = {
    "kahvalt", "salata", "corba", "çorba", "pizza", "burger", "makarna", "tavuk",
    "et ", "balık", "tost", "pilav", "izgara", "tatli", "tatlı", "içecek", "icecek",
    "kahve", "çay", "smoothie", "meze", "kebab", "köfte", "lahmacun", "pide",
    "breakfast", "salad", "soup", "pasta", "chicken", "steak", "grill", "dessert",
    "drink", "sandwich", "appetizer", "main course", "starter",
}


def _content_has_food_items(text, threshold=3):
    text_lower = text.lower()
    return sum(1 for kw in _FOOD_KEYWORDS if kw in text_lower) >= threshold


def _try_wordpress_api(base_parsed, raw_html):
    import requests as http_req

    is_wp = "wp-content" in raw_html or "wp-json" in raw_html or "wordpress" in raw_html.lower()
    if not is_wp:
        return None, []

    origin = f"{base_parsed.scheme}://{base_parsed.netloc}"
    path_parts = [p for p in base_parsed.path.strip("/").split("/") if p]

    slugs_to_try = []
    if path_parts:
        slugs_to_try.append(path_parts[-1])
    slugs_to_try.extend(["menu", "yemek", "yiyecekler", "icecekler", "food", "foods"])

    seen_slugs = set()
    unique_slugs = []
    for s in slugs_to_try:
        if s not in seen_slugs:
            seen_slugs.add(s)
            unique_slugs.append(s)
    slugs_to_try = unique_slugs

    current_app.logger.info(f"[SCRAPER] WordPress detected — trying REST API for slugs: {slugs_to_try}")

    all_sections = SectionAccumulator()
    best_title = None

    for slug in slugs_to_try:
        try:
            api_url = f"{origin}/wp-json/wp/v2/pages?slug={slug}"
            api_resp = _safe_requests_get(api_url, timeout=8, max_bytes=8_000_000, headers={
                "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36",
                "Accept": "application/json",
            })
            if api_resp.status_code != 200 or api_resp.headers.get("Content-Type", "").split(";", 1)[0] != "application/json":
                continue
            pages = bounded_json(api_resp.text)
            if not pages:
                continue

            content_html = pages[0].get("content", {}).get("rendered", "")
            title = pages[0].get("title", {}).get("rendered", "")
            if not content_html:
                continue

            soup = bounded_soup(content_html)
            text = bounded_text(soup)

            if len(text) > 100 and _content_has_food_items(text):
                current_app.logger.info(f"[SCRAPER] WP API hit for slug '{slug}': {len(text)} chars with food content")
                sections = _extract_page_sections(content_html, soup)
                all_sections.extend(sections)
                if not best_title:
                    best_title = title
                continue

            discovered_slugs = set()
            for a in soup.find_all("a", href=True):
                href = a["href"].strip()
                if href.startswith("#") or href.startswith("javascript:") or href.startswith("mailto:"):
                    continue
                if href.startswith("/") or href.startswith(origin):
                    full = href if href.startswith("http") else origin + href
                    link_parsed = http_req.utils.urlparse(full)
                    parts = [p for p in link_parsed.path.strip("/").split("/") if p]
                    if parts and parts[-1] not in seen_slugs:
                        discovered_slugs.add(parts[-1])

            if not best_title:
                best_title = title

            for link_slug in list(discovered_slugs)[:6]:
                seen_slugs.add(link_slug)
                sub_api = f"{origin}/wp-json/wp/v2/pages?slug={link_slug}"
                try:
                    sub_resp = _safe_requests_get(sub_api, timeout=6, max_bytes=8_000_000, headers={
                        "User-Agent": "Mozilla/5.0", "Accept": "application/json"})
                    if sub_resp.status_code != 200 or sub_resp.headers.get("Content-Type", "").split(";", 1)[0] != "application/json":
                        continue
                    sub_pages = bounded_json(sub_resp.text)
                    if not sub_pages:
                        continue
                    sub_html = sub_pages[0].get("content", {}).get("rendered", "")
                    sub_soup = bounded_soup(sub_html)
                    sub_text = bounded_text(sub_soup)
                    if len(sub_text) > 200 and _content_has_food_items(sub_text):
                        current_app.logger.info(f"[SCRAPER] WP API sub-page '{link_slug}': {len(sub_text)} chars with food content")
                        sub_sections = _extract_page_sections(sub_html, sub_soup)
                        all_sections.extend(sub_sections)
                except Exception as e:
                    current_app.logger.warning(f"[SCRAPER] WP API sub-page '{link_slug}' failed: {type(e).__name__}")
                    continue

        except Exception as e:
            current_app.logger.warning(f"[SCRAPER] WP API attempt for '{slug}' failed: {type(e).__name__}")
            continue

    if all_sections:
        current_app.logger.info(f"[SCRAPER] WP API total: {len(all_sections)} sections recovered")
        return str(best_title or "")[:256], bound_sections(all_sections)

    return None, []


def validate_pump_check(image_bytes, location_type, user_description):
    """'Pump Check' doğrulaması: yüklenen ortam fotoğrafının, kullanıcının beyan
    ettiği antrenman ortamıyla (location_type + user_description) uyuşup uyuşmadığını
    kontrol eder. YALNIZCA antrenman tamamlama kanıtı için kullanılır (mobil +
    tarayıcı /complete); menü/beslenme akışları bu fonksiyonu çağırmaz.

    Return: {"valid": bool, "reason": str, "fallback": bool}

    Üç sonuç vardır ve çağıran üçünü ayırt etmek ZORUNDADIR:

    * doğrulandı      → valid=True,  fallback=False  (tamamlama sürebilir)
    * reddedildi      → valid=False, fallback=False  (model değerlendirdi ve "değil"
                        dedi ya da baytlar desteklenen bir görsel değil)
    * doğrulanamadı   → valid=False, fallback=True   (Bedrock 4xx/5xx, zaman aşımı,
                        bozuk model yanıtı, görsel hazırlama hatası…)

    LP-13 P2: kanıt sınırı FAIL-CLOSED'dur. Eskiden her hata valid=True, fallback=True
    döndürüyordu; ≤1.5MB her görsel image/jpeg diye etiketlendiğinden gerçek bir PNG
    Bedrock'tan 400 alıyor ve antrenman doğrulanmadan tamamlanıyordu. Artık
    fallback=True HİÇBİR ZAMAN valid=True ile birlikte dönmez ve medya tipi
    istemcinin beyanından değil baytların kendisinden belirlenir.

    Doğrulayıcının kendisi yoksa (BEDROCK_ENABLED kapalı ya da anthropic paketi
    yüklenemedi) kanıt DEĞERLENDİRİLMEMİŞTİR → doğrulanamadı. Eskiden burada
    valid=True dönen bir "mock" vardı; o da kanıtı değerlendirmeden tamamlamaya
    izin verdiği için kaldırıldı. Başarılı tamamlama bekleyen yerel/test kurulumları
    doğrulayıcıyı açıkça sahtelemelidir."""
    location_type = (location_type or "").strip() or "belirtilmedi"
    user_description = (user_description or "").strip() or "belirtilmedi"

    from app.config import BEDROCK_ENABLED
    from app.services.ai import _bedrock_validate_image, anthropic as _anthropic

    # Bedrock kapalı / istemci yok → kanıt değerlendirilemez: doğrulanamadı
    # (fail-closed, yeniden denenebilir). ASLA "doğrulandı" ya da "reddedildi" değil.
    if not (BEDROCK_ENABLED and _anthropic is not None):
        _log_pump_check("validator_unavailable", media_type=None)
        return _PUMP_CHECK_UNVERIFIED.copy()

    from app.services.vision_images import detect_image_media_type, prepare_image_for_vision

    # Medya tipinin TEK otoritesi baytlardır (dosya adı/istemci Content-Type değil).
    media_type = detect_image_media_type(image_bytes)
    if media_type is None:
        _log_pump_check("unusable_image", media_type=None)
        return {"valid": False, "fallback": False,
                "reason": "Geçerli bir görsel dosyası değil."}

    prompt = (
        f"Sen bir fitness uygulamasının 'Pump Check' doğrulayıcısısın. Kullanıcı şu "
        f"ortamda antrenman yaptığını beyan etti — konum tipi: '{location_type}', "
        f"açıklama: '{user_description}'. Görselin bir spor salonu, ev antrenman alanı "
        f"veya ilgili bir fitness ortamı olup olmadığını ve beyanla uyuşup uyuşmadığını "
        f"değerlendir. SADECE şu katı JSON'u döndür, başka hiçbir şey yazma: "
        f'{{"is_gym": true|false, "reason": "kısa Türkçe gerekçe"}}'
    )

    try:
        # ≤1.5MB → baytlar + tespit edilen tip aynen; büyükse JPEG'e yeniden kodlanır
        # ve tip image/jpeg olur (yeniden kodlanmış baytlar gerçekten JPEG).
        img, sent_type = prepare_image_for_vision(image_bytes, media_type)
        raw = _bedrock_validate_image(img, sent_type, prompt, max_tokens=200)
    except Exception as e:
        # Görsel hazırlama / Bedrock 4xx-5xx / zaman aşımı / bağlantı / bütçe:
        # kanıt DEĞERLENDİRİLMEDİ → doğrulanamadı (fail-closed, yeniden denenebilir).
        _log_pump_check("provider_error", media_type=media_type, error=e)
        return _PUMP_CHECK_UNVERIFIED.copy()

    data = _parse_validation_json(raw)
    is_gym = data.get("is_gym") if isinstance(data, dict) else None
    if not isinstance(is_gym, bool):
        # Model karar vermedi (boş/JSON değil/is_gym yok ya da bool değil). "false"
        # string'i bool("false")=True olurdu; yalnızca gerçek JSON bool kabul edilir.
        _log_pump_check("malformed_response", media_type=media_type)
        return _PUMP_CHECK_UNVERIFIED.copy()
    reason = (str(data.get("reason", "")) or "").strip()[:200]
    if not is_gym:
        _log_pump_check("rejected", media_type=media_type)
    return {
        "valid": is_gym,
        "fallback": False,
        "reason": reason or ("Pump Check doğrulandı." if is_gym else
                             "Fotoğraf belirttiğin antrenman ortamıyla eşleşmedi. "
                             "Antrenman alanını net gösteren bir kare dener misin?"),
    }


_PUMP_CHECK_UNVERIFIED = {
    "valid": False,
    "fallback": True,
    "reason": "Fotoğraf şu an doğrulanamadı. Lütfen biraz sonra tekrar dene.",
}


def _log_pump_check(outcome, *, media_type, error=None):
    """Bounded diagnostics only: no image bytes, base64, model text, user text
    or provider message. ``provider_status`` is the HTTP status class of the
    underlying provider error when one exists (``_bedrock_validate_image`` wraps
    it, so it is read from the exception context)."""
    status = getattr(getattr(error, "__context__", None), "status_code", None)
    status_class = f"{status // 100}xx" if isinstance(status, int) else "-"
    # A model rejection is an ordinary answer; everything else is a failure.
    level = logging.INFO if outcome == "rejected" else logging.WARNING
    current_app.logger.log(
        level,
        "[PUMP CHECK] event=proof_validation outcome=%s media_type=%s "
        "error_type=%s provider_status=%s",
        outcome, media_type or "-",
        type(error).__name__ if error is not None else "-", status_class,
    )


def _parse_validation_json(raw):
    """Modelin ham yanıtından ilk {...} JSON nesnesini ayıkla. Bozuk/eksik girdide
    boş sözlük döner (çağıran fail-open ya da varsayılan değerlerle ilerler)."""
    s = (raw or "").strip().replace("```json", "").replace("```", "")
    start = s.find("{")
    end = s.rfind("}") + 1
    if start != -1 and end > start:
        s = s[start:end]
    try:
        return json.loads(s)
    except (json.JSONDecodeError, TypeError, ValueError):
        return {}


_MENU_WARN_TR = {
    "Exceeds daily budget limit": "Günlük bütçe limitini aşıyor",
    "Approaching calorie budget": "Kalori limitine yaklaşıyor",
    "Approaching fat budget": "Yağ limitine yaklaşıyor",
    "High carbohydrate load": "Yüksek karbonhidrat",
}


def _menu_score(macros, remaining):
    """Menu analizi icin deterministik skor (nutrition_pipeline.score_compatibility)
    -> mevcut (score:int, warnings:[tr], reason:str) sozlesmesi. LLM matematik yapmaz."""
    res = nutrition_pipeline.score_compatibility(macros, remaining)
    flags = res["flags"]
    reason_parts = []
    if "high_protein" in flags:
        reason_parts.append("Yüksek protein")
    if "low_fat" in flags:
        reason_parts.append("Düşük yağ")
    if "fits_calorie_budget" in flags:
        reason_parts.append("Kalori bütçesine uygun")
    if "low_protein_food" in flags:
        reason_parts.append("Protein oranı düşük")
    if not reason_parts:
        reason_parts.append(f"{int(round(macros.get('calories', 0)))} kcal · "
                            f"{int(round(macros.get('protein', 0)))}g protein")
    warnings_tr = [_MENU_WARN_TR.get(w, w) for w in res["warnings"]]
    return res["score"], warnings_tr, " · ".join(reason_parts)
